 act({nombre:'Reunión comercial semanal y reporte de leads y proyectos',descripcion:'Reunión comercial todos los martes donde se tocan todos los temas. Siempre hay una pregunta sobre lo que ha llegado y qué proyectos van saliendo o ejecutándose; el reporte se da a John.',etapa:'ETP-007',actor:'AGT-001',rolProceso:'Reporta el estado de leads y proyectos',infoGenera:'Estado de leads y proyectos (llegados, saliendo, ejecutados)',destinatarioInfo:'John',medioEntrega:'Verbal',sistemas:['SIS-010'],frecuencia:'Semanal (martes)',manual:'Sí',problema:'En Sinergy se veía el porcentaje de avance de cada oportunidad; ahora el estado se comunica de palabra, de forma más manual.',observaciones:'Jairo (ENT-006) la llama «Comité Comercial de los martes»: allí también se revisa la viabilidad de las licitaciones (ACT-059). Quiénes asisten: por confirmar.',duracionDesc:'«Son 2 horas», todos los martes (toda la reunión, no solo el reporte).'});
