 A('ACT-039',{...P4,orden:1,nombre:'Aportar la arquitectura técnica y los costos a la propuesta',descripcion:'En muchas propuestas Proyectos da su opinión sobre la arquitectura, dimensiona personas, horas, cargas, servidores y canales, y en muchos casos da los números para la oferta económica. En licitaciones lee los requisitos y contesta los técnicos [3:37–5:42].',etapa:'ETP-014',actor:'AGT-018',rolProceso:'Dimensiona la solución',infoGenera:'Arquitectura técnica, recursos y costos; a veces los números',destinatarioInfo:'Ingenieros comerciales / preventa',transferenciaAreas:'Sí',observaciones:'Según Alfonso; Preventa no lo mencionó. Quién la solicita, cuándo y por qué medio: no especificado. Quién de Proyectos aporta lo definen Alfonso o Tatiana [7:52–8:00].'});
 A('ACT-027',{...P4,orden:2,nombre:'Recibir el proyecto ganado',descripcion:'Comercial avisa «nos ganamos el proyecto» (a veces por llamada y con «mañana tiene que estar entregando»). Alfonso analiza lo propuesto y exige como mínimo copia del contrato, presupuesto, compromisos, SLA y si se aprobó lo de la preingeniería; «si no, yo no se lo recibo» [28:21–31:31; 44:48–45:04].',etapa:'ETP-015',actor:'AGT-018',rolProceso:'Recibe el negocio ganado',infoRecibe:'Aviso del proyecto ganado; contrato, presupuesto, compromisos, SLA',fuenteInfo:'Comerciales',medioRecibe:'Llamada (caso descrito)',infoRequerida:'Copia del contrato; presupuesto; a qué se comprometieron; SLA; qué se vendió; si se aprobó lo de la preingeniería.',transferenciaAreas:'Sí',espera:'Sí',problema:'La entrega «a veces no se da como se debe dar»: se comprometen sin consultar, exigen empezar al día siguiente y no se entrega la información. Existe un procedimiento escrito que no se ha implementado.',sistemas:['SIS-023'],duracionDesc:'Plazo inmediato: «mañana tiene que estar entregando».'});
 A('ACT-028',{...P4,orden:3,nombre:'Pedir a Comercial la información faltante del proyecto',descripcion:'«No, un momentico. Dígame cuánta plata tengo. Dígame a qué nos comprometimos. ¿Aprobaron el canal que hicimos en la preingeniería?» [44:48–45:04].',etapa:'ETP-015',actor:'AGT-018',infoGenera:'Solicitud de contrato, presupuesto, compromisos y SLA',destinatarioInfo:'Comerciales',reproceso:'Sí',solicitaInfo:'Sí',causaReproceso:'Entrega del proyecto ganado incompleta',problema:'Discusiones fuertes con Comercial; «empezamos con pie izquierdo los proyectos» [28:12; 30:45].',observaciones:'Medio y tiempos de respuesta: no especificados.'});
 A('ACT-029',{...P4,orden:4,nombre:'Reunirse con el cliente y definir las etapas de recepción',descripcion:'«Nos reunimos con el cliente que nos aprobó la oferta, ya la vamos a recibir y definimos unas etapas para recibir ese proyecto»; depende mucho del proyecto [6:23–6:40].',etapa:'ETP-015',actor:'AGT-018',infoGenera:'Etapas de recepción',sistemas:['SIS-024'],observaciones:'Orden exacto respecto a la planificación en Project: por confirmar.'});
 A('ACT-030',{...P4,orden:5,nombre:'Planificar en Project, asignar recursos y hacer kickoff interno',descripcion:'Planificación con metodología PMI (inicio, planeación, ejecución, monitoreo y control, cierre). A cada tarea se le asigna quién la hace según especialidad, disponibilidad, carga y ocupación en otros proyectos, con horas por tarea; luego kickoff interno con responsabilidades [9:20–10:29; 18:07–21:21].',etapa:'ETP-016',actor:'AGT-018',infoRecibe:'Propuesta, compromisos, disponibilidad y carga del equipo',infoGenera:'Cronograma con recursos, horas y responsables',destinatarioInfo:'Equipo del proyecto',sistemas:['SIS-018'],observaciones:'«No todo el equipo sabe manejar Project; normalmente lo utilizo yo» [13:26].',duracionDesc:'La duración del proyecto la define Alfonso: fases PMI, horas por tarea y cronograma (Gantt) en Project. Es el único tiempo que se controla formalmente.'});
 A('ACT-045',{proceso:'PRO-004',fuente:'ENT-003',orden:6,estado:'Borrador',nombre:'Comprar los equipos al proveedor / mayorista',descripcion:'«Si hay que comprar equipos…» se incluye en el cronograma de recepción [11:32–11:40]. El proveedor puede demorar un mes en enviar un equipo [29:45]. Preventa: el plazo informado (30 días) puede pasar a 60 al momento de comprar (ENT-002 [14:12–14:29]).',etapa:'ETP-016',actor:'',infoGenera:'Equipos',espera:'Sí',problema:'Tiempos de entrega del proveedor más largos que los informados.',observaciones:'Quién realiza y aprueba la compra en Proyectos: no especificado. ENT-005 describe el flujo de compras (PRO-007), que parte de un requerimiento de Comercial; que aplique a los equipos de proyectos es posible inferencia — requiere validación. En el comité de los jueves se autorizan compras (ACT-038).',duracionDesc:'El proveedor puede demorar un mes; el plazo informado puede pasar de 30 a 60 días.'});
 A('ACT-031',{...P4,orden:7,nombre:'Ejecutar la implementación',descripcion:'Instalar, configurar, desplegar software, llevar equipos al data center, con la herramienta que se esté implementando (Avaya, «File Night», tipificación…) [10:37–11:40; 15:57–16:42].',etapa:'ETP-017',actor:'AGT-020',infoRecibe:'Cronograma, equipos, plataformas',infoGenera:'Solución implementada',sistemas:['SIS-019']});
 A('ACT-032',{...P4,orden:8,nombre:'Monitorear y controlar costo y tiempo (semáforo)',descripcion:'Indicadores de valor planeado, actual, ganado, rendimiento de costos e índice para la finalización, combinados con el Gantt de Project. Rojo: hay que hacer algo para enderezar el proyecto; amarillo: vigilar; verde: va bien. Lleva el costo de cada proyecto (horas, valor, compras) [22:08–24:08; 32:49–33:09].',etapa:'ETP-017',actor:'AGT-018',infoRecibe:'Avance, horas, costos, compras',infoGenera:'Estado del proyecto (semáforo); análisis y acciones',sistemas:['SIS-018'],observaciones:'Herramienta de los indicadores: no especificada. Qué acción concreta se toma en rojo: no especificada.',duracionDesc:'El tiempo se controla con el semáforo de costo y tiempo frente al Gantt de Project.'});
